style.css:
@-moz-document domain("tiktok.com") {
/* 1. FORCE THE MAIN LAYOUT BACKGROUND TO PITCH BLACK */
    body, 
    html, 
    #app, 
    [class*="DivMainContainer"], 
    [class*="DivBodyContainer"],
    main {
        background-color: #000000 !important;
        background-image: none !important;
    }

    /* 2. ENSURE ALL UPLOADED MEDIA, IMAGES, AND VIDEOS REMAIN FULLY VISIBLE */
    img, 
    video, 
    canvas,
    [class*="DivVideoPlayerContainer"],
    [style*="background-image"] {
        opacity: 1 !important;
        visibility: visible !important;
        display: block !important;
    }

    /* 3. STRICTLY TARGET TEXT COLORS TO BE NEON PURPLE */
    p, 
    span, 
    h1, h2, h3, h4, h5, h6, 
    a, 
    li, 
    strong, 
    div[dir="auto"] {
        color: #9D00FF !important;
    }

    /* 4. OPTIONAL: HIGHLIGHT INTERACTIVE BUTTONS WITH AN ORCHID PINK ACCENT */
    svg, 
    [class*="Button"], 
    [class*="Icon"] {
        color: #E024C3 !important;
        fill: #E024C3 !important;
    }
}
